import{_ as n,l as r,o as e,c as l,v as t,p as s,x as i,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"粘性信息","description":"","frontmatter":{"title":"粘性信息","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/sticky-information.md","filePath":"econ/sticky-information.md","lastUpdated":1789023840000}'),m={name:"econ/sticky-information.md"};function E(h,a,_,f,A,u){const o=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="粘性信息" tabindex="-1">粘性信息 <a class="header-anchor" href="#粘性信息" aria-label="Permalink to &quot;粘性信息&quot;">​</a></h1><div class="epigraph"><p>不是价格不能动，是计划不是每期都基于最新信息重算；老计划与新信息并存，加总出现惯性。</p><footer>—— Mankiw and Reis, Sticky Information versus Sticky Prices, QJE 2002</footer></div><p><a href="/econ/adaptive-learning">上一课</a>让人每期用全部公开数据更新系数。本课缺口是<strong>更新频率</strong>：信息粘性。不重写 E-稳定性，不把 Calvo 价格再推一遍——对照的是另一套惯性来源。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Calvo 粘性价格：每期只有一部分人改价，但改价者用当前 RE。Mankiw–Reis：价格可灵活，但每期只有比例 \\(\\lambda\\) 的人获得新信息并重解计划，其余人沿用旧信息集下的计划。通胀对货币冲击的反应因而缓慢、峰值滞后。缺口是给 NK 惯性一条「信息」通道，而不是再估一个指数化参数。</p><p><span class="marginnote">Mankiw and Reis, <em>QJE</em> 117(4), 2002, 1295–1328。Reis 的粘性信息消费。Carroll 的流行病学预期是相关的传播装置。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>加总通胀是不同 vintage 计划的加权。脉冲：未更新者仍按旧货币路径定价，冲击后通胀慢慢被新 vintage 替换。估计：\\(\\lambda\\) 可用调查预期的更新速度或宏观 IRF。与 SW：习惯、指数化、粘性工资是惯性的其它包；粘性信息可部分替代它们，识别上常共线。</p>',8)),(e(),s(c,null,{default:i(()=>[p(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEWS%5B%22%E6%96%B0%E5%86%B2%E5%87%BB%22%5D%20--%3E%20UPD%5B%22%E6%AF%94%E4%BE%8B%20%CE%BB%20%E6%9B%B4%E6%96%B0%E8%AE%A1%E5%88%92%22%5D%0A%20%20NEWS%20--%3E%20OLD%5B%221-%CE%BB%20%E6%B2%BF%E7%94%A8%E6%97%A7%E8%AE%A1%E5%88%92%22%5D%0A%20%20UPD%20--%3E%20AGG%5B%22%E5%8A%A0%E6%80%BB%E6%83%AF%E6%80%A7%22%5D%0A%20%20OLD%20--%3E%20AGG%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>企业与家庭都可粘性信息。工资设定粘性信息给出劳动侧惯性。财政：未更新者对减税反应迟，乘数动态与 RANK 不同。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是交错的信息集，不是交错的不能改的价格。含义：公布一次完全可信的路径，未更新者仍按旧路径行事，沟通的效力被 \\(\\lambda\\) 打折——后课预期管理。与学习：学习改的是模型系数；粘性信息改的是谁看见了当前冲击。两者可叠：看见的人还在估错的模型。</p><p>最优政策：对未更新者的历史路径依赖，使承诺的价值不同（Reis）。本课不求最优规则。</p><p><span class="marginnote">Woodford 的信息不完全（与 Lucas 岛屿）是另一支：噪声观察而非延迟更新。下一课理性疏忽把延迟变成最优选择。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 \\(\\lambda\\) 写成深度学习注意力。理性疏忽、诊断性预期分列后课。微观价格每天可改却加总惯性，粘性信息是候选，不是唯一（还有搜寻、菜单成本异质）。不进限价簿报价频率。</p><p>后课默认：惯性可以来自计划更新频率，而不只来自 Calvo。下一课：更新频率本身由注意力成本决定。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>粘性信息：交错更新计划，价格可以灵活。</li><li>加总惯性与滞后峰值来自 vintage 混合。</li><li>与学习、Calvo 是不同状态变量。</li><li>出处：Mankiw and Reis, <em>QJE</em> 2002。</li></ul>',10))])}const b=n(m,[["render",E]]);export{k as __pageData,b as default};
